#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe ftp-download-every-file-in-a-folder. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/pub site/pub/archive
printf '%s\n' 'alpha' > site/pub/a.txt
printf '%s\n' 'bravo' > site/pub/b.txt
printf '%s\n' 'charlie' > site/pub/c.txt
printf '%s\n' 'not served' > site/pub/.hidden
printf '%s\n' 'from last year' > site/pub/archive/old.txt
cat > fetch-folder.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# fetch-folder.sh URL DIR: downloads every file of the FTP folder URL (ending in /) into DIR, in one
# curl command, and skips the subfolders. Names with spaces are not handled.
url=$1; dir=$2
mkdir -p "$dir"
# The long listing tells folders from files: a folder's line starts with d.
folders=" $(curl -sS "$url" | tr -d '\r' | awk '/^d/ { print $NF }' | tr '\n' ' ')"
set --
for name in $(curl -sS -l "$url" | tr -d '\r'); do
  case "$folders" in
    *" $name "*) echo "skip $name/" ;;
    *) set -- "$@" -o "$dir/$name" "$url$name" ;;
  esac
done
curl -sS --fail-early -w "get %{url.path} %{exitcode}\n" "$@"
EOF
surl --allow-anonymous --list-directories --directory site ftp://127.0.0.1:8080/ &
sleep 1
sh fetch-folder.sh ftp://127.0.0.1:8080/pub/ out
kill $(jobs -p)
